const body = $input.first().json.body || $input.first().json;

const tipo_zona = body.tipo_zona || 'order_block';
const precio_zona_suelo = parseFloat(body.precio_zona_suelo) || 0;
const precio_zona_techo = parseFloat(body.precio_zona_techo) || 0;
const direccion_precio = body.direccion_precio || 'lateral';
const precio_actual = parseFloat(body.precio_actual) || 0;
const score_1h = parseFloat(body.score_1h) || 50;
const score_15m = parseFloat(body.score_15m) || 50;
const score_5m = parseFloat(body.score_5m) || 50;
const nivel_arriba_tipo = body.nivel_arriba_tipo || null;
const nivel_arriba_precio = body.nivel_arriba_precio ? parseFloat(body.nivel_arriba_precio) : null;
const nivel_abajo_tipo = body.nivel_abajo_tipo || null;
const nivel_abajo_precio = body.nivel_abajo_precio ? parseFloat(body.nivel_abajo_precio) : null;

const score_confluencia = Math.round(score_1h * 0.50 + score_15m * 0.30 + score_5m * 0.20);

const zona_mid = (precio_zona_suelo + precio_zona_techo) / 2;
const distancia_pct = zona_mid > 0 ? Math.abs(precio_actual - zona_mid) / zona_mid * 100 : 99;
let fase = 'LEJOS';
if (precio_actual >= precio_zona_suelo && precio_actual <= precio_zona_techo) {
  fase = 'EN_ZONA';
} else if (distancia_pct < 0.3) {
  fase = 'ACERCANDO';
}

return [{ json: {
  tipo_zona, precio_zona_suelo, precio_zona_techo,
  direccion_precio, precio_actual, score_confluencia, fase,
  nivel_arriba_tipo, nivel_arriba_precio,
  nivel_abajo_tipo, nivel_abajo_precio
}}];

const datosFase = $('Parsear Datos').first().json;
const historialZona = $('Historial Zona Supabase').all().map(i => i.json);
const historialNiveles = $('Historial Niveles Supabase').all().map(i => i.json);

const total = historialZona.length;
let respeto_fuerte = 0, respeto_debil = 0, rompio = 0;
for (const r of historialZona) {
  if (r.resultado === 'respeto_fuerte') respeto_fuerte++;
  else if (r.resultado === 'respeto_debil') respeto_debil++;
  else if (r.resultado === 'rompio') rompio++;
}

const prob_respeto_fuerte = total > 0 ? parseFloat(((respeto_fuerte / total) * 100).toFixed(2)) : 0;
const prob_respeto_debil  = total > 0 ? parseFloat(((respeto_debil  / total) * 100).toFixed(2)) : 0;
const prob_rompio         = total > 0 ? parseFloat(((rompio         / total) * 100).toFixed(2)) : 0;
const muestra_suficiente  = total >= 15;

function calcNivel(tipo) {
  const arr = historialNiveles.filter(n => n.tipo_nivel === tipo);
  const rotos = arr.filter(n => n.fue_roto).length;
  return { prob: arr.length > 0 ? parseFloat(((rotos / arr.length) * 100).toFixed(2)) : 0, casos: arr.length };
}

const arriba = datosFase.nivel_arriba_tipo ? calcNivel(datosFase.nivel_arriba_tipo) : { prob: 0, casos: 0 };
const abajo  = datosFase.nivel_abajo_tipo  ? calcNivel(datosFase.nivel_abajo_tipo)  : { prob: 0, casos: 0 };

return [{ json: {
  id: 1,
  activo: 'XAUUSD',
  tipo_zona: datosFase.tipo_zona,
  precio_zona_suelo: datosFase.precio_zona_suelo,
  precio_zona_techo: datosFase.precio_zona_techo,
  direccion_precio: datosFase.direccion_precio,
  prob_respeto_fuerte, prob_respeto_debil, prob_rompio,
  casos_totales: total,
  muestra_suficiente,
  nivel_arriba_tipo: datosFase.nivel_arriba_tipo,
  nivel_arriba_precio: datosFase.nivel_arriba_precio,
  nivel_arriba_prob_ruptura: arriba.prob,
  nivel_arriba_casos: arriba.casos,
  nivel_abajo_tipo: datosFase.nivel_abajo_tipo,
  nivel_abajo_precio: datosFase.nivel_abajo_precio,
  nivel_abajo_prob_soporte: 100 - abajo.prob,
  nivel_abajo_casos: abajo.casos,
  score_confluencia: datosFase.score_confluencia,
  fase: datosFase.fase,
  updated_at: new Date().toISOString()
}}];
